<script setup lang="ts">
import { onActivated, ref } from 'vue';
import Icon from '../components/Icon.vue';
import { invalidateCapabilities } from '../execution';
const report=ref<any>(),busy=ref(false),error=ref('');
async function inspect() { busy.value=true; error.value=''; try { const r=await fetch('/__runner/toolchain');const value=await r.json();if(!r.ok)throw new Error(value.message);report.value=value.data;invalidateCapabilities(); } catch(e){error.value=(e as Error).message;} finally{busy.value=false;} }
onActivated(inspect);
</script>
<template><div class="page config-page"><div class="page-heading"><div><div class="eyebrow">EXECUTABLES, NOT LABELS</div><h1>真实工具链</h1><p>检测当前执行服务器的实际环境，从工具版本到网页结果，一处核对。</p></div><button class="button" :disabled="busy" @click="inspect"><Icon :name="busy?'loader':'reset'" :class="{spin:busy}" />{{busy?'检测中…':'重新检测'}}</button></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div class="toolchain-summary"><div class="brand-mark"><Icon name="terminal" /></div><div><h2>{{report?`${report.tools.filter((t:any)=>t.available).length} / ${report.tools.length} 项工具可用`:'正在探测本机执行能力'}}</h2><p>{{report?`${report.node} · ${report.platform}`:'检查 Java、JMeter、浏览器与 npm 依赖'}}。安装状态来自实际文件和命令检测。</p></div></div><div v-if="report" class="tool-grid"><article v-for="tool in report.tools" :key="tool.id" class="card tool-card"><div class="section-title"><h2>{{tool.name}}</h2><span :class="['badge',tool.available?'good':'bad']">{{tool.available?'可用':'不可用'}}</span></div><span class="eyebrow">{{tool.purpose}}</span><p>{{tool.detail}}</p><dl><dt>版本</dt><dd>{{tool.version||'未检测到'}}</dd><dt>执行位置</dt><dd class="mono">{{tool.path||'未找到可执行文件'}}</dd></dl><div class="section-title"><a :href="tool.href" class="text-button">打开{{tool.purpose.split(' / ')[0]}}<Icon name="arrow" :size="14" /></a><a v-if="!tool.available" href="#/settings" class="text-button">配置执行器</a></div></article></div><section class="card config-panel"><h2>JMeter → 网页指标</h2><div class="execution-flow"><span>配置请求与负载</span><Icon name="arrow" /><span>生成 JMX</span><Icon name="arrow" /><span>Java 启动 JMeter</span><Icon name="arrow" /><span>解析 JTL / CSV</span><Icon name="arrow" /><span>图表与原始报告</span></div><p class="muted help">在性能测试中选择 Apache JMeter 引擎即可调用。结果包含实际请求样本、TPS、P50 / P95 / P99、错误率；原始 JMX 和结果文件可下载。</p><p class="muted help">浏览器内核：Chromium {{report?.browsers.chromium?'可用':'不可用'}} · Firefox {{report?.browsers.firefox?'可用':'不可用'}} · WebKit {{report?.browsers.webkit?'可用':'不可用'}}</p></section></div></template>
